@@ -0,0 +1,76 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+const storageKey = "viaje-en-familia-state";
+
+function installLocalStorageStub() {
+  const entries = new Map();
+  const localStorage = {
+    getItem(key) {
+      return entries.has(key) ? entries.get(key) : null;
+    },
+    setItem(key, value) {
+      entries.set(key, String(value));
+    },
+    removeItem(key) {
+      entries.delete(key);
+    },
+    clear() {
+      entries.clear();
+    }
+  };
+
+  globalThis.localStorage = localStorage;
+  return { entries, localStorage };
+}
+
+test("persists, reloads and shares state across imports", async () => {
+  const { entries, localStorage } = installLocalStorageStub();
+  const storageModuleUrl = new URL("./storage.mjs", import.meta.url);
+
+  const firstImport = await import(`${storageModuleUrl.href}?first=${Date.now()}`);
+  assert.deepEqual(firstImport.getState(), {});
+
+  const snapshots = [];
+  const unsubscribe = firstImport.subscribe((value) => {
+    snapshots.push(value);
+  });
+
+  const nextState = {
+    trip: {
+      origin: "Buenos Aires",
+      passengers: 4,
+      legs: [{ from: "Buenos Aires", to: "Mendoza" }]
+    }
+  };
+
+  const returned = firstImport.setState(nextState);
+  assert.deepEqual(returned, nextState);
+  assert.deepEqual(firstImport.getState(), nextState);
+  assert.equal(entries.get(storageKey), JSON.stringify(nextState));
+  assert.deepEqual(snapshots, [nextState]);
+
+  const secondImport = await import(`${storageModuleUrl.href}?second=${Date.now()}`);
+  assert.deepEqual(secondImport.getState(), nextState);
+  assert.equal(secondImport.persistenceKey, storageKey);
+  assert.equal(secondImport.subscribe, firstImport.subscribe);
+
+  const persistedPayload = JSON.parse(localStorage.getItem(storageKey));
+  assert.deepEqual(persistedPayload, nextState);
+
+  unsubscribe();
+  firstImport.setState({ trip: { origin: "Córdoba" } });
+  assert.deepEqual(snapshots, [nextState]);
+});
+
+test("recovers from malformed or missing persisted state", async () => {
+  const { localStorage } = installLocalStorageStub();
+  localStorage.setItem(storageKey, "{not valid json");
+
+  const storageModuleUrl = new URL("./storage.mjs", import.meta.url);
+  const storage = await import(`${storageModuleUrl.href}?malformed=${Date.now()}`);
+
+  assert.deepEqual(storage.getState(), {});
+  assert.deepEqual(storage.setState({}), {});
+  assert.equal(localStorage.getItem(storageKey), "{}");
+});

