+}
+
+async function importModules(label) {
+  const storageUrl = new URL("../storage/storage.mjs", import.meta.url);
+  const stopsUrl = new URL("./stops.mjs", import.meta.url);
+
+  const storage = await import(`${storageUrl.href}?${label}=${Date.now()}`);
+  const stops = await import(`${stopsUrl.href}?${label}=${Date.now()}`);
+  return { storage, stops };
