+
+test("creates, edits, deletes and reorders paradas with nombre, fechas and descripcion", async () => {
+  const { entries } = installLocalStorageStub();
+  const { storage, stops } = await importModules("crud");
+
+  storage.setState({});
+
+  const createdA = stops.createStop({
+    name: "Valle de Uco",
+    dates: "2026-12-01 a 2026-12-03",
+    description: "Bodegas y paisaje"
+  });
+  const createdB = stops.createStop({
+    name: "Bariloche",
+    dates: "2026-12-04 a 2026-12-06",
+    description: "Lago y montaña"
+  });
+  const createdC = stops.createStop({
+    name: "Puerto Madryn",
+    dates: "2026-12-07 a 2026-12-09",
+    description: "Costa y fauna"
+  });
+
+  assert.match(createdA.id, /^stop_/);
+  assert.equal(createdA.name, "Valle de Uco");
+  assert.equal(createdA.dates, "2026-12-01 a 2026-12-03");
+  assert.equal(createdA.description, "Bodegas y paisaje");
+
+  assert.deepEqual(stops.getStops().map((stop) => stop.name), [
+    "Valle de Uco",
+    "Bariloche",
+    "Puerto Madryn"
+  ]);
+
+  const updated = stops.updateStop(createdB.id, {
+    name: "San Carlos de Bariloche",
+    dates: "2026-12-05 a 2026-12-06",
+    description: "Lagos y cerros"
+  });
+
+  assert.equal(updated.id, createdB.id);
+  assert.equal(updated.name, "San Carlos de Bariloche");
+  assert.equal(updated.dates, "2026-12-05 a 2026-12-06");
+  assert.equal(updated.description, "Lagos y cerros");
+  assert.deepEqual(stops.getStop(createdB.id), updated);
+
+  const reordered = stops.reorderStops(2, 0);
+  assert.deepEqual(reordered.map((stop) => stop.id), [
+    createdC.id,
+    createdA.id,
+    createdB.id
+  ]);
+  assert.deepEqual(stops.getStops().map((stop) => stop.id), [
+    createdC.id,
+    createdA.id,
+    createdB.id
+  ]);
+
+  assert.equal(stops.deleteStop(createdA.id), true);
+  assert.deepEqual(stops.getStops().map((stop) => stop.id), [
+    createdC.id,
+    createdB.id
+  ]);
+
+  assert.equal(entries.get(storageKey), JSON.stringify({
+    itineraryStops: [
+      {
+        id: createdC.id,
+        name: "Puerto Madryn",
+        dates: "2026-12-07 a 2026-12-09",
+        description: "Costa y fauna"
+      },
+      {
+        id: createdB.id,
+        name: "San Carlos de Bariloche",
+        dates: "2026-12-05 a 2026-12-06",
+        description: "Lagos y cerros"
+      }
+    ]
+  }));
+});
+
+test("persists and reloads the itinerary stops slice through shared storage", async () => {
+  installLocalStorageStub();
+  const { storage, stops } = await importModules("reload");
+
+  storage.setState({
+    trip: { origin: "Buenos Aires" },
+    itineraryStops: [
+      {
+        id: "stop_1",
