+    }
+  ]);
+
+  const secondImport = await import(`${new URL("./stops.mjs", import.meta.url).href}?reload-again=${Date.now()}`);
+  assert.deepEqual(secondImport.getStops(), [
+    {
+      id: "stop_1",
+      name: "Mendoza",
+      dates: "2026-12-01 a 2026-12-03",
+      description: "Vino"
+    }
+  ]);
+  assert.deepEqual(storage.getState().trip, { origin: "Buenos Aires" });
+});
