@@ -0,0 +1,179 @@
+import { getState, setState, subscribe as subscribeState } from "../storage/storage.mjs";
+
+export const budgetKey = "organizationBudget";
+
+function normalizeAmount(value) {
+  const amount = Number(value);
+  return Number.isFinite(amount) && amount > 0 ? amount : 0;
+}
+
+function normalizeCategory(category) {
+  if (typeof category !== "string") {
+    throw new TypeError("category must be a non-empty string");
+  }
+
+  const normalized = category.trim();
+  if (!normalized) {
+    throw new TypeError("category must be a non-empty string");
+  }
+
+  return normalized;
+}
+
+function normalizeExpensesByCategory(value) {
+  const expenses = {};
+
+  if (!value || typeof value !== "object" || Array.isArray(value)) {
+    return expenses;
+  }
+
+  for (const [category, rawAmount] of Object.entries(value)) {
+    const normalizedCategory = normalizeCategory(category);
+    const amount = normalizeAmount(rawAmount);
+
+    if (amount > 0) {
+      expenses[normalizedCategory] = amount;
+    }
+  }
+
+  return expenses;
+}
+
+function sumExpensesByCategory(expensesByCategory) {
+  return Object.values(expensesByCategory).reduce((total, amount) => total + amount, 0);
+}
+
+function normalizeBudget(value) {
+  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
+  const total = normalizeAmount(source.total);
+  const expensesByCategory = normalizeExpensesByCategory(source.expensesByCategory);
+  const spent = sumExpensesByCategory(expensesByCategory);
+  const available = Math.max(0, total - spent);
+  const status = spent > 0 && available === 0 ? "gastado" : "disponible";
+
+  return {
+    total,
+    expensesByCategory,
+    spent,
+    available,
+    status
+  };
+}
+
+function readRootState() {
+  const currentState = getState();
+  return currentState && typeof currentState === "object" && !Array.isArray(currentState) ? currentState : {};
+}
+
+function readBudgetState(rootState = readRootState()) {
+  return normalizeBudget(rootState[budgetKey]);
+}
+
+function writeBudgetState(nextBudget) {
+  const nextState = {
+    ...readRootState(),
+    [budgetKey]: normalizeBudget(nextBudget)
+  };
+
+  setState(nextState);
+  return readBudgetState(nextState);
+}
+
+export function getBudget() {
+  return readBudgetState();
+}
+
+export function setBudgetTotal(total) {
+  const currentBudget = readBudgetState();
+  return writeBudgetState({
+    ...currentBudget,
+    total
+  });
+}
+
+export function setBudgetExpense(category, amount) {
+  const normalizedCategory = normalizeCategory(category);
+  const currentBudget = readBudgetState();
+
+  return writeBudgetState({
+    ...currentBudget,
+    expensesByCategory: {
+      ...currentBudget.expensesByCategory,
+      [normalizedCategory]: amount
+    }
+  });
+}
+
+export function removeBudgetExpense(category) {
+  const normalizedCategory = normalizeCategory(category);
+  const currentBudget = readBudgetState();
+
+  if (!Object.hasOwn(currentBudget.expensesByCategory, normalizedCategory)) {
+    return currentBudget;
+  }
+
+  const nextExpenses = { ...currentBudget.expensesByCategory };
+  delete nextExpenses[normalizedCategory];
+
+  return writeBudgetState({
+    ...currentBudget,
+    expensesByCategory: nextExpenses
+  });
+}
+
+export function clearBudgetExpenses() {
+  const currentBudget = readBudgetState();
+  return writeBudgetState({
+    ...currentBudget,
+    expensesByCategory: {}
+  });
+}
+
+export function getBudgetSummary() {
+  const budget = readBudgetState();
+
+  return {
+    total: budget.total,
+    spent: {
+      amount: budget.spent,
+      state: "gastado"
+    },
+    available: {
+      amount: budget.available,
+      state: "disponible"
+    },
+    status: budget.status
+  };
+}
+
+export function getBudgetCategories() {
+  const budget = readBudgetState();
+
+  return Object.entries(budget.expensesByCategory).map(([category, amount]) => ({
+    category,
+    amount,
+    state: amount > 0 ? "gastado" : "disponible"
+  }));
+}
+
+export function subscribeBudget(listener) {
+  if (typeof listener !== "function") {
+    throw new TypeError("subscribeBudget(listener) expects a function");
+  }
+
+  return subscribeState(() => {
+    listener(readBudgetState());
+  });
+}
+
+export default {
+  budgetKey,
+  getBudget,
+  setBudgetTotal,
+  setBudgetExpense,
+  removeBudgetExpense,
+  clearBudgetExpenses,
+  getBudgetSummary,
+  getBudgetCategories,
+  subscribeBudget
+};
