diff --git a/public/memories-notes/notes.mjs b/public/memories-notes/notes.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..91820be30756989d1df869b31d5398fd5f698ff0
--- /dev/null
+++ b/public/memories-notes/notes.mjs
@@ -0,0 +1,96 @@
+import { getState, setState } from "../storage/storage.mjs";
+
+const notesKey = "notes";
+
+function clone(value) {
+  return value === undefined ? value : JSON.parse(JSON.stringify(value));
+}
+
+function readNotes() {
+  const state = getState();
+  return Array.isArray(state[notesKey]) ? state[notesKey] : [];
+}
+
+function writeNotes(nextNotes) {
+  const state = getState();
+  const nextState = {
+    ...state,
+    [notesKey]: nextNotes
+  };
+
+  setState(nextState);
+  return nextNotes;
+}
+
+function resolveNoteText(input) {
+  const text = input.text ?? input.texto ?? "";
+  if (typeof text !== "string" || text.trim() === "") {
+    throw new TypeError("addNote(note) requires a non-empty text");
+  }
+
+  return text.trim();
+}
+
+function resolveAssociation(input) {
+  const dayId = input.dayId ?? input.diaId ?? "";
+  const stopId = input.stopId ?? input.paradaId ?? "";
+  const hasDay = typeof dayId === "string" && dayId.trim() !== "";
+  const hasStop = typeof stopId === "string" && stopId.trim() !== "";
+
+  if (hasDay === hasStop) {
+    throw new TypeError("addNote(note) requires exactly one association");
+  }
+
+  return {
+    dayId: hasDay ? dayId.trim() : undefined,
+    stopId: hasStop ? stopId.trim() : undefined
+  };
+}
+
+function resolveId(input) {
+  const id = input.id;
+  if (typeof id === "string" && id.trim() !== "") {
+    return id.trim();
+  }
+
+  if (typeof id === "number" && Number.isFinite(id)) {
+    return String(id);
+  }
+
+  return globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+export function getNotes() {
+  return clone(readNotes()) ?? [];
+}
+
+export function getNotesForDay(dayId) {
+  const normalizedDayId = typeof dayId === "string" ? dayId.trim() : String(dayId ?? "");
+  return getNotes().filter((note) => note.dayId === normalizedDayId);
+}
+
+export function getNotesForStop(stopId) {
+  const normalizedStopId = typeof stopId === "string" ? stopId.trim() : String(stopId ?? "");
+  return getNotes().filter((note) => note.stopId === normalizedStopId);
+}
+
+export function addNote(input = {}) {
+  const text = resolveNoteText(input);
+  const association = resolveAssociation(input);
+  const note = {
+    id: resolveId(input),
+    text,
+    createdAt: new Date().toISOString(),
+    ...association
+  };
+
+  const nextNotes = [...readNotes(), note];
+  writeNotes(nextNotes);
+  return clone(note);
+}
+
+export function clearNotes() {
+  return writeNotes([]);
+}
+
+export { notesKey };
