+  return nextStops.map((stop) => clone(stop));
+}
+
+export function moveStop(id, toIndex) {
+  const stops = readStops();
+  const fromIndex = requireStopIndex(stops, id);
+  return reorderStops(fromIndex, toIndex);
+}
