+  assert.deepEqual(JSON.parse(localStorage.getItem("viaje-en-familia-state")), {
+    trip: { origin: "Buenos Aires" },
+    favorites: [place]
+  });
+
+  assert.deepEqual(favorites.removeFavorite(place), []);
+  assert.deepEqual(JSON.parse(localStorage.getItem("viaje-en-familia-state")), {
+    trip: { origin: "Buenos Aires" },
+    favorites: []
+  });
+});

