+const FAVORITES_STATE_KEY = "favorites";
+const KIND_ALIASES = new Map([
+  ["place", "place"],
+  ["places", "place"],
+  ["lugar", "place"],
+  ["lugares", "place"],
+  ["activity", "activity"],
+  ["activities", "activity"],
+  ["actividad", "activity"],
+  ["actividades", "activity"]
+]);
+
+function clone(value) {
+  return value === undefined ? value : JSON.parse(JSON.stringify(value));
+}
+
+function normalizeKind(value) {
+  if (typeof value !== "string") {
+    return null;
+  }
+
+  const normalized = KIND_ALIASES.get(value.trim().toLowerCase());
+  return normalized ?? null;
+}
+
+function normalizeId(value) {
+  if (typeof value === "string" || typeof value === "number") {
+    const normalized = String(value).trim();
+    return normalized === "" ? null : normalized;
+  }
+
+  return null;
+}
+
+function normalizeFavorite(item) {
+  if (!item || typeof item !== "object" || Array.isArray(item)) {
+    throw new TypeError("favorite item must be an object");
+  }
+
+  const kind = normalizeKind(item.kind ?? item.type ?? item.category);
+  if (!kind) {
+    throw new TypeError("favorite item must include a place or activity kind");
+  }
+
+  const id = normalizeId(item.id ?? item.memoryId ?? item.favoriteId);
+  if (!id) {
+    throw new TypeError("favorite item must include an id");
+  }
+
+  const favorite = clone(item) ?? {};
+  favorite.kind = kind;
+  favorite.id = id;
+  delete favorite.type;
+  delete favorite.category;
+  delete favorite.memoryId;
+  delete favorite.favoriteId;
+  return favorite;
+}
+
+function tryNormalizeFavorite(item) {
+  try {
+    return normalizeFavorite(item);
+  } catch {
+    return null;
+  }
+}
+
+function favoriteKey(item) {
+  return `${item.kind}:${item.id}`;
+}
+
+function readFavoriteItems() {
+  const state = getState();
+  const favorites = state[FAVORITES_STATE_KEY];
+  if (!Array.isArray(favorites)) {
+    return [];
+  }
+
+  return favorites.map(tryNormalizeFavorite).filter(Boolean);
+}
+
+function writeFavoriteItems(nextFavoriteItems) {
+  const state = getState();
+  setState({
+    ...state,
+    [FAVORITES_STATE_KEY]: nextFavoriteItems
+  });
+  return getFavorites();
+}
+
+function upsertFavoriteItem(item) {
+  const favorite = normalizeFavorite(item);
+  const currentItems = readFavoriteItems();
+  const key = favoriteKey(favorite);
+  const existingIndex = currentItems.findIndex((entry) => favoriteKey(entry) === key);
+
+  const nextItems = currentItems.slice();
+  if (existingIndex === -1) {
+    nextItems.push(favorite);
+  } else {
+    nextItems[existingIndex] = favorite;
+  }
+
+  return writeFavoriteItems(nextItems);
+}
+
+function removeFavoriteItem(item) {
+  const favorite = normalizeFavorite(item);
+  const key = favoriteKey(favorite);
+  const nextItems = readFavoriteItems().filter((entry) => favoriteKey(entry) !== key);
+  return writeFavoriteItems(nextItems);
+}
+
+export function getFavorites() {
+  return clone(readFavoriteItems()) ?? [];
+}
+
+export function getFavoriteMemories() {
+  return getFavorites();
+}
+
+export function isFavorite(item) {
+  const favorite = normalizeFavorite(item);
+  const key = favoriteKey(favorite);
+  return readFavoriteItems().some((entry) => favoriteKey(entry) === key);
+}
+
+export function addFavorite(item) {
+  return upsertFavoriteItem(item);
+}
+
+export function removeFavorite(item) {
+  return removeFavoriteItem(item);
+}
+
+export function setFavorite(item, shouldBeFavorite) {
+  return shouldBeFavorite ? addFavorite(item) : removeFavorite(item);
+}
+
+export function toggleFavorite(item) {
+  return isFavorite(item) ? removeFavorite(item) : addFavorite(item);
+}
+
+export function subscribe(listener) {
+  if (typeof listener !== "function") {
+    throw new TypeError("subscribe(listener) expects a function");
+  }
+
+  return subscribeStorage(() => {
+    listener(getFavorites());
+  });
+}
+
+export const subscribeFavorites = subscribe;
