+import {
+  getState,
+  setState,
+  subscribe
+} from "../storage/storage.mjs";
+
+const explorerStateKey = "exploracion";
+
+function normalizeText(value) {
+  return String(value ?? "")
+    .normalize("NFD")
+    .replace(/[\u0300-\u036f]/g, "")
+    .toLowerCase()
+    .trim();
+}
+
+function asArray(value) {
+  return Array.isArray(value) ? value : [];
+}
+
+function getItineraryItems(state = getState()) {
+  const trip = state?.trip ?? {};
+  return asArray(state?.itinerary).concat(asArray(trip?.itinerary));
+}
+
+function getExplorerState(state = getState()) {
+  const current = state?.[explorerStateKey];
+  return current && typeof current === "object" && !Array.isArray(current) ? current : {};
+}
+
+function getExplorerCriteria(state = getState()) {
+  const current = getExplorerState(state);
+  return {
+    query: typeof current.query === "string" ? current.query : "",
+    kind: current.kind === "stop" || current.kind === "activity" ? current.kind : "all"
+  };
+}
+
+function matchesQuery(item, query) {
+  const needle = normalizeText(query);
+  if (!needle) return true;
+
+  const haystack = [
+    item?.name,
+    item?.title,
+    item?.label,
+    item?.description,
+    item?.city,
+    item?.location,
+    item?.category,
+    item?.kind,
+    item?.type,
+    ...(Array.isArray(item?.tags) ? item.tags : []),
+    ...(Array.isArray(item?.keywords) ? item.keywords : [])
+  ]
+    .map(normalizeText)
+    .filter(Boolean);
+
+  return haystack.some((value) => value.includes(needle));
+}
+
+function matchesKind(item, kind) {
+  if (kind === "all") return true;
+  return normalizeText(item?.kind ?? item?.type) === kind;
+}
+
+function filterItineraryItems(items, criteria = {}) {
+  const query = typeof criteria.query === "string" ? criteria.query : "";
+  const kind = criteria.kind === "stop" || criteria.kind === "activity" ? criteria.kind : "all";
+
+  return asArray(items).filter((item) => matchesKind(item, kind) && matchesQuery(item, query));
+}
+
+function getFilteredItineraryItems(state = getState(), criteria = getExplorerCriteria(state)) {
+  return filterItineraryItems(getItineraryItems(state), criteria);
+}
+
+function setExplorerCriteria(nextCriteria = {}) {
+  const currentState = getState();
+  const previous = getExplorerState(currentState);
+  const nextState = {
+    ...currentState,
+    [explorerStateKey]: {
+      ...previous,
+      ...nextCriteria
+    }
+  };
+
+  return setState(nextState);
+}
+
+function subscribeExplorer(listener) {
+  return subscribe(listener);
+}
+
+export {
+  explorerStateKey,
+  filterItineraryItems,
+  getExplorerCriteria,
+  getExplorerState,
+  getFilteredItineraryItems,
+  getItineraryItems,
+  matchesKind,
+  matchesQuery,
+  normalizeText,
+  setExplorerCriteria,
+  subscribeExplorer
+};
+
+export { getState, setState, subscribe };
+
