+import { getState, setState } from "../storage/storage.mjs";
+
+export const stopsStateKey = "itineraryStops";
+
+function clone(value) {
+  return value === undefined ? value : JSON.parse(JSON.stringify(value));
+}
+
+function isRecord(value) {
+  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
+}
+
+function normalizeText(value) {
+  return typeof value === "string" ? value.trim() : "";
+}
+
+function pickField(input, primary, fallback) {
+  if (primary in input) return input[primary];
+  if (fallback in input) return input[fallback];
+  return undefined;
+}
+
+function createStopId() {
+  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `stop_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
+}
+
+function normalizeStop(input, fallbackId = createStopId()) {
+  if (!isRecord(input)) {
+    throw new TypeError("stop must be an object");
+  }
+
+  return {
+    id: typeof input.id === "string" && input.id.trim() ? input.id : fallbackId,
+    name: normalizeText(pickField(input, "name", "nombre")),
+    dates: clone(pickField(input, "dates", "fechas")),
+    description: normalizeText(pickField(input, "description", "descripcion"))
+  };
+}
+
+function readState() {
+  const state = getState();
+  return isRecord(state) ? state : {};
+}
+
+function readStops() {
+  const state = readState();
+  const stops = state[stopsStateKey];
+  return Array.isArray(stops) ? stops.map((stop) => normalizeStop(stop, stop?.id)) : [];
+}
+
+function writeStops(nextStops) {
+  const state = readState();
+  const nextState = {
+    ...state,
+    [stopsStateKey]: nextStops.map((stop) => clone(stop))
+  };
+
+  setState(nextState);
+  return nextStops.map((stop) => clone(stop));
+}
+
+function requireStopIndex(stops, id) {
+  const index = stops.findIndex((stop) => stop.id === id);
+  if (index === -1) {
+    throw new RangeError(`Stop not found: ${id}`);
+  }
+
+  return index;
+}
+
+function clampIndex(index, length) {
+  if (!Number.isInteger(index)) {
+    throw new TypeError("index must be an integer");
+  }
+
+  if (length <= 0) return 0;
+  return Math.min(Math.max(index, 0), length - 1);
+}
+
+export function getStops() {
+  return readStops().map((stop) => clone(stop));
+}
+
+export function getStop(id) {
+  const stops = readStops();
+  const stop = stops.find((item) => item.id === id);
+  return stop ? clone(stop) : null;
+}
+
+export function createStop(input) {
+  const stops = readStops();
+  const stop = normalizeStop(input);
+  const nextStops = [...stops, stop];
+  writeStops(nextStops);
+  return clone(stop);
+}
+
+export function updateStop(id, patch) {
+  if (!isRecord(patch)) {
+    throw new TypeError("patch must be an object");
+  }
+
+  const stops = readStops();
+  const index = requireStopIndex(stops, id);
+  const current = stops[index];
+  const nextStop = normalizeStop(
+    {
+      ...current,
+      ...patch,
+      id: current.id
+    },
+    current.id
+  );
+
+  const nextStops = [...stops];
+  nextStops[index] = nextStop;
+  writeStops(nextStops);
+  return clone(nextStop);
+}
+
+export function deleteStop(id) {
+  const stops = readStops();
+  const index = requireStopIndex(stops, id);
+  const nextStops = stops.filter((stop, stopIndex) => stopIndex !== index);
+  writeStops(nextStops);
+  return true;
+}
+
+export function reorderStops(fromIndex, toIndex) {
+  const stops = readStops();
+  if (!Number.isInteger(fromIndex) || !Number.isInteger(toIndex)) {
+    throw new TypeError("fromIndex and toIndex must be integers");
+  }
+
+  if (stops.length === 0) {
+    return [];
+  }
+
+  const sourceIndex = clampIndex(fromIndex, stops.length);
+  const targetIndex = clampIndex(toIndex, stops.length);
+
+  if (sourceIndex === targetIndex) {
+    return getStops();
+  }
+
+  const nextStops = [...stops];
+  const [moved] = nextStops.splice(sourceIndex, 1);
+  nextStops.splice(targetIndex, 0, moved);
+  writeStops(nextStops);
+  return nextStops.map((stop) => clone(stop));
+}
+
+export function moveStop(id, toIndex) {
+  const stops = readStops();
+  const fromIndex = requireStopIndex(stops, id);
+  return reorderStops(fromIndex, toIndex);
+}
