+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { getState, setState } from "../storage/storage.mjs";
+
+const notesModuleUrl = new URL("./notes.mjs", import.meta.url);
+
+function installLocalStorageStub() {
+  const entries = new Map();
+  const localStorage = {
+    getItem(key) {
+      return entries.has(key) ? entries.get(key) : null;
+    },
+    setItem(key, value) {
+      entries.set(key, String(value));
+    },
+    removeItem(key) {
+      entries.delete(key);
+    },
+    clear() {
+      entries.clear();
+    }
+  };
+
+  globalThis.localStorage = localStorage;
+  return { entries, localStorage };
+}
+
+test("stores a note for a day and persists it", async () => {
+  const { entries } = installLocalStorageStub();
+  setState({});
+
+  const notes = await import(`${notesModuleUrl.href}?day=${Date.now()}`);
+  const created = notes.addNote({
+    text: "Comprar agua",
+    diaId: "dia-1"
+  });
+
+  assert.equal(created.text, "Comprar agua");
+  assert.equal(created.diaId, "dia-1");
+  assert.equal(created.dayId, "dia-1");
+  assert.equal(created.paradaId, undefined);
+
+  assert.deepEqual(notes.getNotes(), [created]);
+  assert.deepEqual(notes.getNotesForDay("dia-1"), [created]);
+  assert.deepEqual(notes.getNotesForStop("dia-1"), []);
+  assert.deepEqual(getState().notes, [created]);
+  assert.equal(entries.get("viaje-en-familia-state"), JSON.stringify({ notes: [created] }));
+
+  const notesReloaded = await import(`${notesModuleUrl.href}?day-reload=${Date.now()}`);
+  assert.deepEqual(notesReloaded.getNotes(), [created]);
+});
+
+test("stores a note for a stop and keeps notes isolated by association", async () => {
+  installLocalStorageStub();
+  setState({});
+
+  const notes = await import(`${notesModuleUrl.href}?stop=${Date.now()}`);
+  const first = notes.addNote({
+    texto: "Parar para merendar",
+    paradaId: "parada-7"
+  });
+  const second = notes.addNote({
+    text: "Mirar el mapa",
+    stopId: "parada-7"
+  });
+
+  assert.equal(first.paradaId, "parada-7");
+  assert.equal(second.paradaId, "parada-7");
+  assert.equal(first.stopId, "parada-7");
+  assert.equal(second.stopId, "parada-7");
+  assert.deepEqual(notes.getNotesForStop("parada-7"), [first, second]);
+  assert.deepEqual(notes.getNotesForDay("parada-7"), []);
+  assert.equal(getState().notes.length, 2);
+});

