+import assert from "node:assert/strict";
+import test from "node:test";
+
+const storageKey = "viaje-en-familia-state";
+
+function installLocalStorageStub() {
+  const entries = new Map();
+
+  globalThis.localStorage = {
+    getItem(key) {
+      return entries.has(key) ? entries.get(key) : null;
+    },
+    setItem(key, value) {
+      entries.set(key, String(value));
+    },
+    removeItem(key) {
+      entries.delete(key);
+    },
+    clear() {
+      entries.clear();
+    }
+  };
+
+  return entries;
+}
+
+test("carga presupuesto total, gastos por categoria y estados visuales", async () => {
+  const entries = installLocalStorageStub();
+  const budgetModuleUrl = new URL("./budget.mjs", import.meta.url);
+  const budget = await import(`${budgetModuleUrl.href}?case=budget-${Date.now()}`);
+
+  assert.deepEqual(budget.getBudget(), {
+    total: 0,
+    expensesByCategory: {},
+    spent: 0,
+    available: 0,
+    status: "disponible"
+  });
+
+  const snapshots = [];
+  const unsubscribe = budget.subscribeBudget((value) => {
+    snapshots.push(value);
+  });
+
+  assert.deepEqual(budget.setBudgetTotal(120), {
+    total: 120,
+    expensesByCategory: {},
+    spent: 0,
+    available: 120,
+    status: "disponible"
+  });
+
+  assert.deepEqual(budget.setBudgetExpense("transporte", 45), {
+    total: 120,
+    expensesByCategory: { transporte: 45 },
+    spent: 45,
+    available: 75,
+    status: "disponible"
+  });
+
+  assert.deepEqual(budget.setBudgetExpense("alojamiento", 75), {
+    total: 120,
+    expensesByCategory: { transporte: 45, alojamiento: 75 },
+    spent: 120,
+    available: 0,
+    status: "gastado"
+  });
+
+  assert.deepEqual(budget.getBudgetSummary(), {
+    total: 120,
+    spent: {
+      amount: 120,
+      state: "gastado"
+    },
+    available: {
+      amount: 0,
+      state: "disponible"
+    },
+    status: "gastado"
+  });
+
+  assert.deepEqual(budget.getBudgetCategories(), [
+    { category: "transporte", amount: 45, state: "gastado" },
+    { category: "alojamiento", amount: 75, state: "gastado" }
+  ]);
+
+  assert.deepEqual(snapshots, [
+    {
+      total: 120,
+      expensesByCategory: {},
+      spent: 0,
+      available: 120,
+      status: "disponible"
+    },
+    {
+      total: 120,
+      expensesByCategory: { transporte: 45 },
+      spent: 45,
+      available: 75,
+      status: "disponible"
+    },
+    {
+      total: 120,
+      expensesByCategory: { transporte: 45, alojamiento: 75 },
+      spent: 120,
+      available: 0,
+      status: "gastado"
+    }
+  ]);
+
+  assert.equal(entries.get(storageKey), JSON.stringify({
+    organizationBudget: {
+      total: 120,
+      expensesByCategory: { transporte: 45, alojamiento: 75 },
+      spent: 120,
+      available: 0,
+      status: "gastado"
+    }
+  }));
+
+  unsubscribe();
+});
+
+test("preserva el estado compartido y elimina gastos por categoria", async () => {
+  const entries = installLocalStorageStub();
+  const storage = await import("../storage/storage.mjs");
+  storage.setState({
+    trip: { origin: "Buenos Aires" }
+  });
+
+  const budgetModuleUrl = new URL("./budget.mjs", import.meta.url);
+  const budget = await import(`${budgetModuleUrl.href}?case=budget-remove-${Date.now()}`);
+
+  assert.deepEqual(budget.setBudgetTotal(80), {
+    total: 80,
+    expensesByCategory: {},
+    spent: 0,
+    available: 80,
+    status: "disponible"
+  });
+
+  assert.deepEqual(budget.setBudgetExpense("comidas", 30), {
+    total: 80,
+    expensesByCategory: { comidas: 30 },
+    spent: 30,
+    available: 50,
+    status: "disponible"
+  });
+
+  assert.deepEqual(budget.removeBudgetExpense("comidas"), {
+    total: 80,
+    expensesByCategory: {},
+    spent: 0,
+    available: 80,
+    status: "disponible"
+  });
+
+  assert.deepEqual(storage.getState(), {
+    trip: { origin: "Buenos Aires" },
+    organizationBudget: {
+      total: 80,
+      expensesByCategory: {},
+      spent: 0,
+      available: 80,
+      status: "disponible"
+    }
+  });
+
+  assert.equal(entries.get(storageKey), JSON.stringify({
+    trip: { origin: "Buenos Aires" },
+    organizationBudget: {
+      total: 80,
+      expensesByCategory: {},
+      spent: 0,
+      available: 80,
+      status: "disponible"
+    }
+  }));
+});

