+import { getState, setState } from "../storage/storage.mjs";
+
+const notesKey = "notes";
+
+function clone(value) {
+  return value === undefined ? value : JSON.parse(JSON.stringify(value));
+}
+
+function readNotes() {
+  const state = getState();
+  return Array.isArray(state[notesKey]) ? state[notesKey] : [];
+}
+
+function decorateNote(note) {
+  const decorated = clone(note);
+  if (!decorated || typeof decorated !== "object") {
+    return decorated;
+  }
+
+  if ("diaId" in decorated && !("dayId" in decorated)) {
+    Object.defineProperty(decorated, "dayId", {
+      enumerable: false,
+      configurable: true,
+      get() {
+        return decorated.diaId;
+      }
+    });
+  }
+
+  if ("paradaId" in decorated && !("stopId" in decorated)) {
+    Object.defineProperty(decorated, "stopId", {
+      enumerable: false,
+      configurable: true,
+      get() {
+        return decorated.paradaId;
+      }
+    });
+  }
+
+  return decorated;
+}
+
+function writeNotes(nextNotes) {
+  const state = getState();
+  const nextState = {
+    ...state,
+    [notesKey]: nextNotes
+  };
+
+  setState(nextState);
+  return nextNotes;
+}
+
+function resolveNoteText(input) {
+  const text = input.text ?? input.texto ?? "";
+  if (typeof text !== "string" || text.trim() === "") {
+    throw new TypeError("addNote(note) requires a non-empty text");
+  }
+
+  return text.trim();
+}
+
+function resolveAssociation(input) {
+  const diaId = input.diaId ?? input.dayId ?? "";
+  const paradaId = input.paradaId ?? input.stopId ?? "";
+  const hasDia = typeof diaId === "string" && diaId.trim() !== "";
+  const hasParada = typeof paradaId === "string" && paradaId.trim() !== "";
+
+  if (hasDia === hasParada) {
+    throw new TypeError("addNote(note) requires exactly one association");
+  }
+
+  return {
+    diaId: hasDia ? diaId.trim() : undefined,
+    paradaId: hasParada ? paradaId.trim() : undefined
+  };
+}
+
+function resolveId(input) {
+  const id = input.id;
+  if (typeof id === "string" && id.trim() !== "") {
+    return id.trim();
+  }
+
+  if (typeof id === "number" && Number.isFinite(id)) {
+    return String(id);
+  }
+
+  return globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+export function getNotes() {
+  return readNotes().map(decorateNote);
+}
+
+export function getNotesForDay(dayId) {
+  const normalizedDayId = typeof dayId === "string" ? dayId.trim() : String(dayId ?? "");
+  return getNotes().filter((note) => note.diaId === normalizedDayId);
+}
+
+export function getNotesForDia(diaId) {
+  return getNotesForDay(diaId);
+}
+
+export function getNotesForStop(stopId) {
+  const normalizedStopId = typeof stopId === "string" ? stopId.trim() : String(stopId ?? "");
+  return getNotes().filter((note) => note.paradaId === normalizedStopId);
+}
+
+export function getNotesForParada(paradaId) {
+  return getNotesForStop(paradaId);
+}
+
