+  if (!Array.isArray(stops)) return [];
+
+  return stops
+    .filter(isRecord)
+    .map((stop) => normalizeStop(stop, stop.id));
+}
+
+function writeStops(nextStops) {
+  const state = readState();
+  const nextState = {
+    ...state,
+    [stopsStateKey]: nextStops.map((stop) => clone(stop))
+  };
+
+  setState(nextState);
+  return nextStops.map((stop) => clone(stop));
+}
+
+function requireStopIndex(stops, id) {
+  const index = stops.findIndex((stop) => stop.id === id);
+  if (index === -1) {
+    throw new RangeError(`Stop not found: ${id}`);
+  }
+
+  return index;
+}
+
+function clampIndex(index, length) {
+  if (!Number.isInteger(index)) {
+    throw new TypeError("index must be an integer");
+  }
+
+  if (length <= 0) return 0;
+  return Math.min(Math.max(index, 0), length - 1);
