+import {
+  getState as getStorageState,
+  setState as setStorageState,
+  subscribe as subscribeStorage
+} from "../storage/storage.mjs";
+
+const stateKey = "agendaDiaria";
+const allowedStates = new Set(["pendiente", "completada"]);
+
+function clone(value) {
+  return value === undefined ? value : JSON.parse(JSON.stringify(value));
+}
+
+function normalizeActividad(value) {
+  const actividad = value && typeof value === "object" && !Array.isArray(value) ? value : {};
+  const estado = allowedStates.has(actividad.estado) ? actividad.estado : "pendiente";
+
+  return {
+    dia: actividad.dia ?? "",
+    parada: actividad.parada ?? "",
+    horario: actividad.horario ?? "",
+    estado
+  };
+}
+
+function normalizeAgenda(value) {
+  if (!Array.isArray(value)) return [];
+  return value.map(normalizeActividad);
+}
+
+function readAgendaState() {
+  return normalizeAgenda(getStorageState()[stateKey]);
+}
+
+function writeAgendaState(nextAgenda) {
+  const nextStorageState = getStorageState();
+
+  if (nextAgenda.length === 0) {
+    delete nextStorageState[stateKey];
+  } else {
+    nextStorageState[stateKey] = nextAgenda;
+  }
+
+  setStorageState(nextStorageState);
+  return getState();
+}
+
+function extractAgenda(next) {
+  if (Array.isArray(next)) return next;
+  if (next && typeof next === "object") {
+    if (Array.isArray(next[stateKey])) return next[stateKey];
+  }
+
+  return [];
+}
+
+export function getState() {
+  return { [stateKey]: clone(readAgendaState()) };
+}
+
+export function setState(next) {
+  return writeAgendaState(normalizeAgenda(extractAgenda(next)));
+}
+
+export function subscribe(listener) {
+  if (typeof listener !== "function") {
+    throw new TypeError("subscribe(listener) expects a function");
+  }
+
+  return subscribeStorage(() => listener(getState()));
+}
+
+export function getAgendaDiaria() {
+  return clone(readAgendaState());
+}
+
+export function setAgendaDiaria(next) {
+  return setState(next);
+}
+
+export function addActividad(actividad) {
+  const nextAgenda = [...readAgendaState(), normalizeActividad(actividad)];
+  return writeAgendaState(nextAgenda);
+}
+
+export function completarActividad(index) {
+  const nextAgenda = readAgendaState().map((actividad, currentIndex) => {
+    if (currentIndex !== index) return actividad;
+    return { ...actividad, estado: "completada" };
+  });
+
+  return writeAgendaState(nextAgenda);
+}
+
+export function reabrirActividad(index) {
+  const nextAgenda = readAgendaState().map((actividad, currentIndex) => {
+    if (currentIndex !== index) return actividad;
+    return { ...actividad, estado: "pendiente" };
+  });
+
+  return writeAgendaState(nextAgenda);
+}
+
+export { stateKey as agendaKey };
