+import assert from "node:assert/strict";
+import test from "node:test";
+
+const storageKey = "viaje-en-familia-state";
+const packingKey = "packingChecklist";
+
+function installLocalStorageStub() {
+  const entries = new Map();
+  const localStorage = {
+    getItem(key) {
+      return entries.has(key) ? entries.get(key) : null;
+    },
+    setItem(key, value) {
+      entries.set(key, String(value));
+    },
+    removeItem(key) {
+      entries.delete(key);
+    },
+    clear() {
+      entries.clear();
+    }
+  };
+
+  globalThis.localStorage = localStorage;
+  return { entries, localStorage };
+}
+
+async function importPackingModule(tag) {
+  const packingModuleUrl = new URL("./packing.mjs", import.meta.url);
+  return import(`${packingModuleUrl.href}?${tag}=${Date.now()}`);
+}
+
+test("el checklist de equipaje agrega, completa y filtra items", async () => {
+  installLocalStorageStub();
+  const packing = await importPackingModule("agrega");
+
+  assert.deepEqual(packing.getPackingChecklist(), {
+    items: [],
+    filter: "all"
+  });
+
+  const afterFirstAdd = packing.addPackingItem("Pasaporte");
+  const afterSecondAdd = packing.addPackingItem("Cargador");
+
+  assert.equal(afterFirstAdd.items.length, 1);
+  assert.equal(afterSecondAdd.items.length, 2);
+  assert.equal(afterSecondAdd.items[0].label, "Pasaporte");
+  assert.equal(afterSecondAdd.items[1].completed, false);
+  assert.deepEqual(packing.getVisiblePackingItems().map((item) => item.label), ["Pasaporte", "Cargador"]);
+
+  const completedChecklist = packing.completePackingItem(afterSecondAdd.items[0].id);
+  assert.equal(completedChecklist.items[0].completed, true);
+  assert.equal(completedChecklist.items[1].completed, false);
+
+  const completedFilter = packing.setPackingFilter("completed");
+  assert.equal(completedFilter.filter, "completed");
+  assert.deepEqual(packing.getVisiblePackingItems().map((item) => item.label), ["Pasaporte"]);
+
+  const pendingFilter = packing.setPackingFilter("pending");
+  assert.equal(pendingFilter.filter, "pending");
+  assert.deepEqual(packing.getVisiblePackingItems().map((item) => item.label), ["Cargador"]);
+});
+
+test("el checklist de equipaje reporta el progreso total y persiste en storage", async () => {
+  const { localStorage } = installLocalStorageStub();
+  const packing = await importPackingModule("progreso");
+
+  const first = packing.addPackingItem("Documento");
+  const second = packing.addPackingItem("Medicamentos");
+  packing.completePackingItem(second.items[1].id);
+
+  assert.deepEqual(packing.getPackingProgress(), {
+    completed: 1,
+    total: 2,
+    percentage: 50,
+    progress: 50
+  });
