+    items: [
+      {
+        id: first.items[0].id,
+        label: "Documento",
+        completed: false
+      },
+      {
+        id: second.items[1].id,
+        label: "Medicamentos",
+        completed: true
+      }
+    ],
+    filter: "all"
+  });
+});

diff --git a/public/organization-packing/packing.mjs b/public/organization-packing/packing.mjs
