+import { getState, setState } from "../storage/storage.mjs";
+
+const stateKey = "itineraryStops";
+
+function isRecord(value) {
+  return value !== null && typeof value === "object" && !Array.isArray(value);
+}
+
+function clone(value) {
+  return value === undefined ? value : JSON.parse(JSON.stringify(value));
+}
+
+function createId() {
+  return globalThis.crypto?.randomUUID?.() ?? `stop-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function toText(value) {
+  return value === undefined || value === null ? "" : String(value);
+}
+
+function normalizeStop(input = {}, fallbackId = createId()) {
+  const source = isRecord(input) ? input : {};
+  const fechas = isRecord(source.fechas) ? source.fechas : {};
+
+  return {
+    id: toText(source.id || fallbackId),
+    nombre: toText(source.nombre ?? source.name),
+    fechaInicio: toText(source.fechaInicio ?? source.startDate ?? fechas.inicio ?? fechas.startDate),
+    fechaFin: toText(source.fechaFin ?? source.endDate ?? fechas.fin ?? fechas.endDate),
+    descripcion: toText(source.descripcion ?? source.description)
+  };
+}
+
+function readStops() {
+  const state = getState();
+  const stops = Array.isArray(state[stateKey]) ? state[stateKey] : [];
+  return stops.map((stop) => normalizeStop(stop, stop?.id));
+}
+
+function writeStops(nextStops) {
+  const nextState = getState();
+  nextState[stateKey] = nextStops.map((stop) => normalizeStop(stop, stop.id));
+  setState(nextState);
+  return getStops();
+}
+
+export function getStops() {
+  return clone(readStops()) ?? [];
+}
+
+export function getStopById(id) {
+  return getStops().find((stop) => stop.id === String(id)) ?? null;
+}
+
+export function createStop(input = {}) {
+  const nextStop = normalizeStop(input);
+  writeStops([...readStops(), nextStop]);
+  return getStopById(nextStop.id);
+}
+
+export function updateStop(id, patch = {}) {
+  const stops = readStops();
+  const index = stops.findIndex((stop) => stop.id === String(id));
+  if (index === -1) return null;
+
+  const updated = normalizeStop({ ...stops[index], ...patch, id: stops[index].id }, stops[index].id);
+  stops.splice(index, 1, updated);
+  writeStops(stops);
+  return getStopById(updated.id);
+}
+
+export function deleteStop(id) {
+  const stops = readStops();
+  const index = stops.findIndex((stop) => stop.id === String(id));
+  if (index === -1) return null;
+
+  const [removed] = stops.splice(index, 1);
+  writeStops(stops);
+  return removed ?? null;
+}
+
+export function moveStop(id, toIndex) {
+  const stops = readStops();
+  const fromIndex = stops.findIndex((stop) => stop.id === String(id));
+  if (fromIndex === -1) return getStops();
+
+  const nextIndexRaw = Number(toIndex);
+  const nextIndex = Number.isFinite(nextIndexRaw) ? Math.max(0, Math.min(Math.trunc(nextIndexRaw), stops.length - 1)) : stops.length - 1;
+  const nextStops = stops.slice();
+  const [stop] = nextStops.splice(fromIndex, 1);
+  const insertIndex = Math.max(0, Math.min(nextIndex, nextStops.length));
+  nextStops.splice(insertIndex, 0, stop);
+  return writeStops(nextStops);
+}
+
+export function reorderStops(order = []) {
+  if (!Array.isArray(order)) return getStops();
+
+  const stops = readStops();
+  const byId = new Map(stops.map((stop) => [stop.id, stop]));
+  const seen = new Set();
+  const nextStops = [];
+
+  for (const rawId of order) {
+    const stop = byId.get(String(rawId));
+    if (!stop || seen.has(stop.id)) continue;
+    seen.add(stop.id);
+    nextStops.push(stop);
+  }
+
+  for (const stop of stops) {
+    if (seen.has(stop.id)) continue;
+    nextStops.push(stop);
+  }
+
+  return writeStops(nextStops);
+}
+
+export function clearStops() {
+  return writeStops([]);
+}
+
+export const crearParada = createStop;
+export const editarParada = updateStop;
+export const eliminarParada = deleteStop;
+export const moverParada = moveStop;
+export const reordenarParadas = reorderStops;
+
+export default {
+  getStops,
+  getStopById,
+  createStop,
+  updateStop,
+  deleteStop,
+  moveStop,
+  reorderStops,
+  clearStops,
+  crearParada,
+  editarParada,
+  eliminarParada,
+  moverParada,
+  reordenarParadas
+};
