+export function createStop(input = {}) {
+  const nextStop = normalizeStop(input);
+  writeStops([...readStops(), nextStop]);
+  return getStopById(nextStop.id);
+}
+
+export function updateStop(id, patch = {}) {
+  const stops = readStops();
+  const index = stops.findIndex((stop) => stop.id === String(id));
+  if (index === -1) return null;
+
+  const updated = normalizeStop({ ...stops[index], ...patch, id: stops[index].id }, stops[index].id);
