+      {
+        id: secondItem.items[1].id,
+        label: "Cargador",
+        completed: true
+      }
+    ],
+    filter: "all"
+  });
+
+  assert.deepEqual(integration.getOrganizationState(), {
+    budget: {
+      total: 180,
+      expensesByCategory: { transporte: 60 },
+      spent: 60,
+      available: 120,
+      status: "disponible"
+    },
+    packingChecklist: {
+      items: [
+        {
+          id: firstItem.items[0].id,
+          label: "Pasaporte",
+          completed: false
+        },
+        {
+          id: secondItem.items[1].id,
+          label: "Cargador",
+          completed: true
+        }
+      ],
+      filter: "all"
+    },
+    budgetSummary: {
+      total: 180,
+      spent: {
+        amount: 60,
+        state: "gastado"
+      },
+      available: {
+        amount: 120,
+        state: "disponible"
+      },
+      status: "disponible"
+    },
+    packingProgress: {
+      completed: 1,
+      total: 2,
+      percentage: 50,
+      progress: 50
+    }
+  });
+
+  assert.deepEqual(integration.getOrganizationView(), integration.getOrganizationState());
+  assert.deepEqual(integration.getOrganizationBudgetSummary(), budget.getBudgetSummary());
+  assert.deepEqual(integration.getOrganizationPackingProgress(), packing.getPackingProgress());
+
+  assert.equal(snapshots.length, 5);
+  assert.deepEqual(snapshots.at(-1), integration.getOrganizationState());
+  assert.equal(entries.get(storageKey), JSON.stringify({
+    organizationBudget: {
+      total: 180,
+      expensesByCategory: { transporte: 60 },
+      spent: 60,
+      available: 120,
+      status: "disponible"
+    },
+    packingChecklist: {
+      items: [
+        {
+          id: firstItem.items[0].id,
+          label: "Pasaporte",
+          completed: false
+        },
+        {
+          id: secondItem.items[1].id,
+          label: "Cargador",
+          completed: true
+        }
+      ],
+      filter: "all"
+    }
+  }));
+
+  unsubscribe();
