index 0000000000000000000000000000000000000000..335f81441efd18126dcc0420f7df530b3fc254d3
--- /dev/null
+++ b/public/organization-integration/organization.integration.mjs
@@ -0,0 +1,77 @@
+const budgetModuleUrl = new URL("../organization-budget/budget.mjs", import.meta.url);
+
+const packingModuleUrl = new URL("../organization-packing/packing.mjs", import.meta.url);
+
+const storageModuleUrl = new URL("../storage/storage.mjs", import.meta.url);
+
+const budgetModule = await import(budgetModuleUrl.href);
+const packingModule = await import(packingModuleUrl.href);
+const { subscribe: subscribeState } = await import(storageModuleUrl.href);
+
+const {
+  getBudget,
+  getBudgetSummary
+} = budgetModule;
+
+const {
+  getPackingChecklist,
+  getPackingProgress
+} = packingModule;
+
+export const organizationKey = "organization";
+
+export function getOrganizationBudget() {
+  return getBudget();
+}
+
+export const getOrganizationBudgetState = getOrganizationBudget;
+
+export function getOrganizationPackingChecklist() {
+  return getPackingChecklist();
+}
+
+export const getOrganizationPackingChecklistState = getOrganizationPackingChecklist;
+
+export function getOrganizationState() {
+  return {
+    budget: getOrganizationBudget(),
+    packingChecklist: getOrganizationPackingChecklist(),
+    budgetSummary: getBudgetSummary(),
+    packingProgress: getPackingProgress()
+  };
+}
+
+export const getOrganizationView = getOrganizationState;
+
+export function getOrganizationBudgetSummary() {
+  return getBudgetSummary();
+}
+
+export function getOrganizationPackingProgress() {
+  return getPackingProgress();
+}
+
+export function subscribeOrganization(listener) {
+  if (typeof listener !== "function") {
+    throw new TypeError("subscribeOrganization(listener) expects a function");
+  }
+
+  return subscribeState(() => {
+    listener(getOrganizationState());
+  });
+}
+
+export const organizationIntegration = {
+  organizationKey,
+  getOrganizationBudget,
+  getOrganizationBudgetState,
+  getOrganizationPackingChecklist,
+  getOrganizationPackingChecklistState,
+  getOrganizationState,
+  getOrganizationView,
+  getOrganizationBudgetSummary,
+  getOrganizationPackingProgress,
+  subscribeOrganization
+};
+
+export default organizationIntegration;
diff --git a/public/organization-integration/organization.integration.test.mjs b/public/organization-integration/organization.integration.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..27e7302af3f5319736b954e7e9c03d78ce9fa721
--- /dev/null
+++ b/public/organization-integration/organization.integration.test.mjs
@@ -0,0 +1,222 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+const storageKey = "viaje-en-familia-state";
+
+function installLocalStorageStub() {
+  const entries = new Map();
+
+  globalThis.localStorage = {
+    getItem(key) {
+      return entries.has(key) ? entries.get(key) : null;
+    },
+    setItem(key, value) {
+      entries.set(key, String(value));
+    },
+    removeItem(key) {
+      entries.delete(key);
+    },
+    clear() {
+      entries.clear();
+    }
+  };
+
+  return entries;
+}
+
+async function resetSharedState(tag) {
+  const storageModuleUrl = new URL("../storage/storage.mjs", import.meta.url);
+  const storage = await import(storageModuleUrl.href);
+  storage.setState({});
+}
+
+async function importIntegration(tag) {
+  const integrationModuleUrl = new URL("./organization.integration.mjs", import.meta.url);
+  return import(`${integrationModuleUrl.href}?${tag}=${Date.now()}`);
+}
+
+async function importBudget(tag) {
+  const budgetModuleUrl = new URL("../organization-budget/budget.mjs", import.meta.url);
+  return import(budgetModuleUrl.href);
+}
+
+async function importPacking(tag) {
+  const packingModuleUrl = new URL("../organization-packing/packing.mjs", import.meta.url);
+  return import(packingModuleUrl.href);
+}
+
+test("expone presupuesto y checklist de equipaje en una vista integrada", async () => {
+  const entries = installLocalStorageStub();
+  const tag = "vista";
+  await resetSharedState(tag);
+
+  const integration = await importIntegration(tag);
+  const budget = await importBudget(tag);
+  const packing = await importPacking(tag);
+
+  const snapshots = [];
+  const unsubscribe = integration.subscribeOrganization((value) => {
+    snapshots.push(value);
+  });
+
+  budget.setBudgetTotal(180);
+  budget.setBudgetExpense("transporte", 60);
+  const firstItem = packing.addPackingItem("Pasaporte");
+  const secondItem = packing.addPackingItem("Cargador");
+  packing.completePackingItem(secondItem.items[1].id);
+
+  assert.deepEqual(integration.getOrganizationBudget(), {
+    total: 180,
+    expensesByCategory: { transporte: 60 },
+    spent: 60,
+    available: 120,
+    status: "disponible"
+  });
+
+  assert.deepEqual(integration.getOrganizationPackingChecklist(), {
+    items: [
+      {
+        id: firstItem.items[0].id,
+        label: "Pasaporte",
+        completed: false
+      },
+      {
+        id: secondItem.items[1].id,
+        label: "Cargador",
+        completed: true
+      }
+    ],
+    filter: "all"
+  });
+
+  assert.deepEqual(integration.getOrganizationState(), {
+    budget: {
+      total: 180,
+      expensesByCategory: { transporte: 60 },
+      spent: 60,
+      available: 120,
+      status: "disponible"
+    },
+    packingChecklist: {
+      items: [
+        {
+          id: firstItem.items[0].id,
+          label: "Pasaporte",
+          completed: false
+        },
+        {
+          id: secondItem.items[1].id,
+          label: "Cargador",
+          completed: true
+        }
+      ],
+      filter: "all"
+    },
+    budgetSummary: {
+      total: 180,
+      spent: {
+        amount: 60,
+        state: "gastado"
+      },
+      available: {
+        amount: 120,
+        state: "disponible"
+      },
+      status: "disponible"
+    },
+    packingProgress: {
+      completed: 1,
+      total: 2,
+      percentage: 50,
+      progress: 50
+    }
+  });
+
+  assert.deepEqual(integration.getOrganizationView(), integration.getOrganizationState());
+  assert.deepEqual(integration.getOrganizationBudgetSummary(), budget.getBudgetSummary());
+  assert.deepEqual(integration.getOrganizationPackingProgress(), packing.getPackingProgress());
+
+  assert.equal(snapshots.length, 5);
+  assert.deepEqual(snapshots.at(-1), integration.getOrganizationState());
+  assert.equal(entries.get(storageKey), JSON.stringify({
+    organizationBudget: {
+      total: 180,
+      expensesByCategory: { transporte: 60 },
+      spent: 60,
+      available: 120,
+      status: "disponible"
+    },
+    packingChecklist: {
+      items: [
+        {
+          id: firstItem.items[0].id,
+          label: "Pasaporte",
+          completed: false
+        },
+        {
+          id: secondItem.items[1].id,
+          label: "Cargador",
+          completed: true
+        }
+      ],
+      filter: "all"
+    }
+  }));
+
+  unsubscribe();
+});
+
+test("rechaza suscriptores inválidos y conserva el estado compartido", async () => {
+  installLocalStorageStub();
+  const tag = "estado";
+  await resetSharedState(tag);
+
+  const integration = await importIntegration(tag);
+  const budget = await importBudget(tag);
+  const packing = await importPacking(tag);
+
+  assert.throws(() => integration.subscribeOrganization(null), {
+    name: "TypeError"
+  });
+
+  budget.setBudgetTotal(90);
+  packing.addPackingItem("Documento");
+
+  assert.deepEqual(integration.getOrganizationState(), {
+    budget: {
+      total: 90,
+      expensesByCategory: {},
+      spent: 0,
+      available: 90,
+      status: "disponible"
+    },
+    packingChecklist: {
+      items: [
+        {
+          id: packing.getPackingChecklist().items[0].id,
+          label: "Documento",
+          completed: false
+        }
+      ],
+      filter: "all"
+    },
+    budgetSummary: {
+      total: 90,
+      spent: {
+        amount: 0,
+        state: "gastado"
+      },
+      available: {
+        amount: 90,
+        state: "disponible"
+      },
+      status: "disponible"
+    },
+    packingProgress: {
+      completed: 0,
+      total: 1,
+      percentage: 0,
+      progress: 0
+    }
+  });
+});

