function normalizeAmount(value) {
  const amount = Number(value);
  return Number.isFinite(amount) && amount > 0 ? amount : 0;
}

function normalizeCategory(category, { strict = true } = {}) {
  if (typeof category !== "string") {
    if (strict) {
      throw new TypeError("category must be a non-empty string");
    }

    return null;
  }

  const normalized = category.trim();
  if (!normalized) {
    if (strict) {
      throw new TypeError("category must be a non-empty string");
    }

    return null;
  }

  return normalized;
}

function normalizeExpensesByCategory(value) {
  const expenses = {};

  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return expenses;
  }

  for (const [category, rawAmount] of Object.entries(value)) {
    const normalizedCategory = normalizeCategory(category, { strict: false });
    if (!normalizedCategory) {
      continue;
    }

    const amount = normalizeAmount(rawAmount);

    if (amount > 0) {
      expenses[normalizedCategory] = amount;
    }
  }

  return expenses;
}

function sumExpensesByCategory(expensesByCategory) {
  return Object.values(expensesByCategory).reduce((total, amount) => total + amount, 0);
}

function normalizeBudget(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const total = normalizeAmount(source.total);
  const expensesByCategory = normalizeExpensesByCategory(source.expensesByCategory);
  const spent = sumExpensesByCategory(expensesByCategory);
  const available = Math.max(0, total - spent);
  const status = spent > 0 && available === 0 ? "gastado" : "disponible";

  return {
    total,
    expensesByCategory,
    spent,
    available,
    status
  };
}

function readRootState() {
  const currentState = getState();
  return currentState && typeof currentState === "object" && !Array.isArray(currentState) ? currentState : {};
}

