import assert from "node:assert/strict";
import test from "node:test";

const storageKey = "viaje-en-familia-state";

function installLocalStorageStub() {
  const entries = new Map();

  globalThis.localStorage = {
    getItem(key) {
      return entries.has(key) ? entries.get(key) : null;
    },
    setItem(key, value) {
      entries.set(key, String(value));
    },
    removeItem(key) {
      entries.delete(key);
    },
    clear() {
      entries.clear();
    }
  };

  return entries;
}

async function importWithCase(relativePath, caseTag) {
  const moduleUrl = new URL(relativePath, import.meta.url);
  return import(`${moduleUrl.href}?case=${caseTag}`);
}

test("la vista de organizacion conserva presupuesto y checklist en el mismo storage", async () => {
  const entries = installLocalStorageStub();
  const caseTag = `organization-${Date.now()}`;

  const storage = await importWithCase("../storage/storage.mjs", caseTag);
  storage.setState({});

  const budget = await importWithCase("../organization-budget/budget.mjs", caseTag);
  const packing = await importWithCase("../organization-packing/packing.mjs", caseTag);

  assert.deepEqual(budget.getBudget(), {
    total: 0,
    expensesByCategory: {},
    spent: 0,
    available: 0,
    status: "disponible"
  });

  assert.deepEqual(packing.getPackingChecklist(), {
    items: [],
    filter: "all"
  });

  const afterBudget = budget.setBudgetTotal(240);
  assert.deepEqual(afterBudget, {
    total: 240,
    expensesByCategory: {},
    spent: 0,
    available: 240,
    status: "disponible"
  });

  assert.deepEqual(storage.getState(), {
    organizationBudget: afterBudget
  });

  const afterPackingAdd = packing.addPackingItem("Pasaporte");
  assert.equal(afterPackingAdd.items.length, 1);
  assert.equal(afterPackingAdd.items[0].label, "Pasaporte");

  assert.deepEqual(storage.getState(), {
    organizationBudget: afterBudget,
    packingChecklist: {
      items: [
        {
          id: afterPackingAdd.items[0].id,
          label: "Pasaporte",
          completed: false
        }
      ],
      filter: "all"
    }
  });

  const afterBudgetExpense = budget.setBudgetExpense("alojamiento", 120);
  assert.deepEqual(afterBudgetExpense, {
    total: 240,
    expensesByCategory: { alojamiento: 120 },
    spent: 120,
    available: 120,
    status: "disponible"
  });

  const afterPackingComplete = packing.completePackingItem(afterPackingAdd.items[0].id);
  assert.equal(afterPackingComplete.items[0].completed, true);

  assert.deepEqual(budget.getBudgetSummary(), {
    total: 240,
    spent: {
      amount: 120,
      state: "gastado"
    },
    available: {
      amount: 120,
      state: "disponible"
    },
    status: "disponible"
  });

  assert.deepEqual(packing.getPackingProgress(), {
    completed: 1,
    total: 1,
    percentage: 100,
    progress: 100
  });

  assert.deepEqual(storage.getState(), {
    organizationBudget: {
      total: 240,
      expensesByCategory: { alojamiento: 120 },
      spent: 120,
      available: 120,
      status: "disponible"
    },
    packingChecklist: {
      items: [
        {
          id: afterPackingAdd.items[0].id,
          label: "Pasaporte",
          completed: true
        }
      ],
      filter: "all"
    }
  });

  assert.equal(entries.get(storageKey), JSON.stringify({
    organizationBudget: {
      total: 240,
      expensesByCategory: { alojamiento: 120 },
      spent: 120,
      available: 120,
      status: "disponible"
    },
    packingChecklist: {
      items: [
        {
          id: afterPackingAdd.items[0].id,
          label: "Pasaporte",
          completed: true
        }
      ],
      filter: "all"
    }
  }));
});


