const STATE_KEY = "packingChecklist";
const FILTERS = new Set(["all", "pending", "completed"]);
let nextId = 0;

function clone(value) {
  return value === undefined ? value : JSON.parse(JSON.stringify(value));
}

function createEmptyChecklist() {
  return {
    items: [],
    filter: "all"
  };
}

function normalizeFilter(value) {
  return FILTERS.has(value) ? value : "all";
}

function normalizeItem(item) {
  if (!item || typeof item !== "object") {
    return null;
  }

  const id = typeof item.id === "string" && item.id.length > 0 ? item.id : null;
  const label = typeof item.label === "string" ? item.label.trim() : "";
  if (!id || !label) {
    return null;
  }

  return {
    id,
    label,
    completed: Boolean(item.completed)
  };
}

function normalizeChecklist(value) {
  const base = createEmptyChecklist();

  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return base;
  }

  const items = Array.isArray(value.items)
    ? value.items.map(normalizeItem).filter(Boolean)
    : [];

  return {
    items,
    filter: normalizeFilter(value.filter)
  };
}

function readChecklist() {
  return normalizeChecklist(getState()[STATE_KEY]);
}

function writeChecklist(nextChecklist) {
  const nextState = clone(getState()) ?? {};
  nextState[STATE_KEY] = normalizeChecklist(nextChecklist);
  setState(nextState);
  return getPackingChecklist();
}

function createId() {
  const crypto = globalThis.crypto;
  if (crypto && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }

  nextId += 1;
  return `packing-${Date.now().toString(36)}-${nextId.toString(36)}`;
}

export function getPackingChecklist() {
  return readChecklist();
}

export function addPackingItem(label) {
  const normalizedLabel = typeof label === "string" ? label.trim() : "";
  if (!normalizedLabel) {
    throw new TypeError("addPackingItem(label) expects a non-empty string");
  }

  const checklist = readChecklist();
  checklist.items = checklist.items.concat({
    id: createId(),
    label: normalizedLabel,
    completed: false
  });

  return writeChecklist(checklist);
}

export function completePackingItem(id) {
  if (typeof id !== "string" || id.length === 0) {
    throw new TypeError("completePackingItem(id) expects a non-empty string");
  }

  const checklist = readChecklist();
  checklist.items = checklist.items.map((item) =>
    item.id === id ? { ...item, completed: !item.completed } : item
  );

  return writeChecklist(checklist);
}

export const togglePackingItem = completePackingItem;

export function setPackingFilter(filter) {
  const checklist = readChecklist();
  checklist.filter = normalizeFilter(filter);
  return writeChecklist(checklist);
}

export const addItem = addPackingItem;
export const completeItem = completePackingItem;
export const setFilter = setPackingFilter;

export function getVisiblePackingItems() {
